PRAGMA foreign_keys=ON;
CREATE TABLE projects(id TEXT PRIMARY KEY, name TEXT NOT NULL, root TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE episodes(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, ordinal INTEGER NOT NULL, UNIQUE(project_id,ordinal));
CREATE TABLE shots(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), episode_id TEXT NOT NULL REFERENCES episodes(id), code TEXT NOT NULL, ordinal INTEGER NOT NULL, current_revision INTEGER NOT NULL DEFAULT 0, UNIQUE(project_id,code));
CREATE TABLE shot_revisions(id TEXT PRIMARY KEY, shot_id TEXT NOT NULL REFERENCES shots(id), revision INTEGER NOT NULL, manifest_json TEXT NOT NULL, resolved_registry_json TEXT NOT NULL, input_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(shot_id,revision));
CREATE TABLE asset_versions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), registry_id TEXT NOT NULL, kind TEXT NOT NULL, version INTEGER NOT NULL, relative_path TEXT, metadata_json TEXT NOT NULL, checksum TEXT, created_at TEXT NOT NULL, UNIQUE(project_id,registry_id,version));
CREATE TABLE artifact_versions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), shot_id TEXT NOT NULL REFERENCES shots(id), role TEXT NOT NULL, version INTEGER NOT NULL, input_hash TEXT NOT NULL, relative_path TEXT, provenance TEXT NOT NULL, validity TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(shot_id,role,version));
CREATE TABLE subsystem_states(shot_id TEXT NOT NULL REFERENCES shots(id), subsystem TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('AUTO','MANUAL')), lock_state TEXT NOT NULL CHECK(lock_state IN ('UNLOCKED','LOCKED')), validity TEXT NOT NULL CHECK(validity IN ('CURRENT','STALE')), review TEXT NOT NULL CHECK(review IN ('NEEDS_REVIEW','APPROVED')), state_revision INTEGER NOT NULL, synced_fingerprint TEXT, observed_fingerprint TEXT, PRIMARY KEY(shot_id,subsystem));
CREATE TABLE approvals(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), scope TEXT NOT NULL, scope_id TEXT NOT NULL, exact_version INTEGER NOT NULL, decision_json TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,scope,scope_id,exact_version));
CREATE TABLE jobs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), shot_id TEXT NOT NULL REFERENCES shots(id), shot_revision INTEGER NOT NULL, subsystem TEXT NOT NULL, operation_id TEXT NOT NULL UNIQUE, input_hash TEXT NOT NULL, profile_version TEXT NOT NULL, state TEXT NOT NULL, expected_state_revision INTEGER NOT NULL, provider_request_id TEXT, resource TEXT NOT NULL, adapter_kind TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE job_attempts(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), attempt INTEGER NOT NULL, state TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, receipt_id TEXT, UNIQUE(job_id,attempt));
CREATE TABLE job_dependencies(job_id TEXT NOT NULL REFERENCES jobs(id), depends_on_id TEXT NOT NULL REFERENCES jobs(id), PRIMARY KEY(job_id,depends_on_id));
CREATE TABLE receipts(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL UNIQUE, input_hash TEXT NOT NULL, status TEXT NOT NULL, output_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE resource_leases(resource TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), acquired_at TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT, event_type TEXT NOT NULL, entity_id TEXT NOT NULL, detail_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_jobs_state ON jobs(state,created_at);
CREATE INDEX idx_audit_id ON audit(id);
